CREATE TYPE property_state AS ENUM ('Draft','Ready','Published','Archived');
CREATE TYPE verification_state AS ENUM ('Unknown','Realtor-provided','Verified','Not applicable');
CREATE TABLE users(id uuid PRIMARY KEY, name text NOT NULL, email text UNIQUE NOT NULL, password_hash text NOT NULL, authentication_identity text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE auth_attempts(key text PRIMARY KEY, attempts integer NOT NULL DEFAULT 1, window_start timestamptz NOT NULL DEFAULT now());
CREATE TABLE properties(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, status property_state NOT NULL DEFAULT 'Draft', title text, street_address text, city text, province text, postal_code text, country text, property_type text CHECK(property_type IN ('Detached house','Townhouse','Condo','Duplex','Other')), listing_price numeric(15,2) CHECK(listing_price>0), description text, revision integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz);
CREATE INDEX property_owner ON properties(owner_id,updated_at DESC);
CREATE TABLE property_details(property_id uuid PRIMARY KEY REFERENCES properties ON DELETE CASCADE,
 bedrooms integer CHECK(bedrooms>=0),full_bathrooms integer CHECK(full_bathrooms>=0),half_bathrooms integer CHECK(half_bathrooms>=0),interior_sqft numeric CHECK(interior_sqft>0),year_built integer,lot_size numeric CHECK(lot_size>0),annual_tax numeric CHECK(annual_tax>=0),hoa_fee numeric CHECK(hoa_fee>=0),additional_fees numeric CHECK(additional_fees>=0),fee_frequency text,fee_inclusions text,
 flooring text,appliances text,storage text,renovations text,laundry text,basement text,fireplace boolean,
 heating text,cooling text,water_heating text,electrical text,plumbing text,internet text,roof_year integer,
 balcony boolean,patio boolean,backyard boolean,fence boolean,garage boolean,driveway boolean,parking_spaces integer CHECK(parking_spaces>=0),parking_type text,rental_rules text,pet_rules text,age_rules text,other_rules text);
CREATE TABLE property_facts(property_id uuid NOT NULL REFERENCES properties ON DELETE CASCADE, fact_key text NOT NULL, text_value text, number_value numeric, boolean_value boolean, verification verification_state NOT NULL DEFAULT 'Unknown',source_reference text NOT NULL DEFAULT '',updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(property_id,fact_key),CHECK(num_nonnulls(text_value,number_value,boolean_value)<=1));
CREATE TABLE property_rooms(id uuid PRIMARY KEY,property_id uuid NOT NULL REFERENCES properties ON DELETE CASCADE,name text NOT NULL,room_type text NOT NULL DEFAULT '',floor text NOT NULL DEFAULT '',length numeric CHECK(length>0),width numeric CHECK(width>0),unit text NOT NULL CHECK(unit IN ('ft','m')),description text NOT NULL DEFAULT '',features text[] NOT NULL DEFAULT '{}',ceiling_height numeric CHECK(ceiling_height>0),orientation text NOT NULL DEFAULT '',natural_light text NOT NULL DEFAULT '',window_count integer CHECK(window_count>=0),closet text NOT NULL DEFAULT '',updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,property_id));
CREATE TABLE property_media(id uuid PRIMARY KEY,property_id uuid NOT NULL REFERENCES properties ON DELETE CASCADE,room_id uuid,storage_key text NOT NULL UNIQUE,description text NOT NULL DEFAULT '',display_order integer NOT NULL DEFAULT 0,is_cover boolean NOT NULL DEFAULT false,mime_type text NOT NULL,byte_size integer NOT NULL CHECK(byte_size>0),uploaded_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(room_id,property_id) REFERENCES property_rooms(id,property_id));
CREATE UNIQUE INDEX one_cover_per_property ON property_media(property_id) WHERE is_cover;
CREATE INDEX media_property ON property_media(property_id,display_order);
CREATE TABLE property_documents(id uuid PRIMARY KEY,property_id uuid NOT NULL REFERENCES properties ON DELETE CASCADE,title text NOT NULL,kind text NOT NULL,storage_reference text NOT NULL,access_level text NOT NULL CHECK(access_level IN ('Private','Realtor-approved')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE storage_deletions(storage_key text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION queue_media_deletion() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO storage_deletions(storage_key) VALUES(OLD.storage_key) ON CONFLICT DO NOTHING; RETURN OLD; END $$;
CREATE TRIGGER media_delete_cleanup BEFORE DELETE ON property_media FOR EACH ROW EXECUTE FUNCTION queue_media_deletion();
